import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

export default function createNode(config, ctx) {
    const { Group, Mesh, PlaneGeometry } = ctx.THREE;

    // Root container
    const root = new Group();

    // -------------------------------------------------
    // 1. Textured plane (static, no lighting)
    // -------------------------------------------------
    // Use texture aspect ratio (512 / 320 = 1.6) – plane size 1.6 × 1.0 units
    const planeWidth = 1.6;
    const planeHeight = 1.0;

    const geometry = new PlaneGeometry(planeWidth, planeHeight);
    const material = new MeshBasicNodeMaterial({ color: 0xffffff, transparent: true });
    const plane = new Mesh(geometry, material);
    root.add(plane);

    // Load texture asynchronously (function stays sync)
    if (config.imageUrl) {
        ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
            material.map = tex;
            material.needsUpdate = true;
        });
    }

    // -------------------------------------------------
    // 2. Headline text label
    // -------------------------------------------------
    const textItems = config.textContent ??
        config.intent?.visualSpec?.textContent ??
        [];

    const textObjects = [];

    for (const item of textItems) {
        const opts = {
            fontSize: (item.typography && item.typography.fontSize) || 39,
            color: (item.role === 'headline' ? config.colors?.paper : config.colors?.paper) || '#e8ecf2',
            align: 'center',
        };
        const txt = ctx.fontAtlas.createText(item.text, opts);
        // Position the text slightly in front of the plane (z +0.01) and centered vertically
        txt.position.set(0, 0, 0.01);
        root.add(txt);
        textObjects.push(txt);
    }

    // -------------------------------------------------
    // 3. UserData – handlers and cleanup
    // -------------------------------------------------
    root.userData.handlers = {};

    // Store references for cleanup
    const disposables = {
        geometry,
        material,
        textures: [], // will be populated when texture loads
        timelines: [], // none for this node, kept for consistency
    };

    // Capture texture load to dispose later
    if (config.imageUrl) {
        ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
            disposables.textures.push(tex);
        });
    }

    root.userData.cleanup = () => {
        // Dispose timelines (none expected)
        disposables.timelines.forEach((tl) => {
            if (tl && tl.kill) tl.kill();
        });

        // Dispose material and geometry
        if (material) material.dispose();
        if (geometry) geometry.dispose();

        // Dispose loaded textures
        disposables.textures.forEach((tex) => {
            if (tex && tex.dispose) tex.dispose();
        });

        // Remove children (meshes, texts) from scene graph
        root.traverse((obj) => {
            if (obj !== root && obj.parent) {
                obj.parent.remove(obj);
                if (obj.geometry) obj.geometry.dispose?.();
                if (obj.material) obj.material.dispose?.();
            }
        });
    };

    return root;
}
